import{_ as o,o as a,c as r,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Membros e papéis","description":"","frontmatter":{},"headers":[],"relativePath":"pt-BR/guide/members.md","filePath":"pt-BR/guide/members.md"}'),s={name:"pt-BR/guide/members.md"};function t(d,e,n,l,m,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="membros-e-papeis" tabindex="-1">Membros e papéis <a class="header-anchor" href="#membros-e-papeis" aria-label="Permalink to &quot;Membros e papéis&quot;">​</a></h1><p>Um workspace pode ter mais gente do que o administrador que instalou o Orbit. Cada pessoa tem um papel em cada workspace de que participa, e o Orbit confere esse papel em todo pedido.</p><h2 id="roles" tabindex="-1">Papéis <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Papéis {#roles}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Papel</th><th>Pode</th></tr></thead><tbody><tr><td>Proprietário</td><td>Tudo no workspace, inclusive os membros e outros proprietários</td></tr><tr><td>Admin</td><td>Tudo menos gerenciar proprietários: criar e apagar projetos, ambientes e bancos de dados, domínios, integrações, canais de notificação, armazenamentos de backup, restaurações, credenciais e membros</td></tr><tr><td>Desenvolvedor</td><td>Fazer deploy e rollback, mudar configurações de build, variáveis e recursos, rodar jobs, fazer backup, navegar nos dados de um banco, abrir um <a href="./applications#terminal">terminal</a> nas instâncias de uma aplicação e ler repositórios dos provedores Git conectados</td></tr><tr><td>Leitor</td><td>Ver tudo menos valores secretos, credenciais e os dados de um banco</td></tr></tbody></table><ul><li><strong>O que fica com admins e proprietários:</strong> restaurar um backup, apagar qualquer coisa, revelar ou trocar as credenciais de um banco, abrir o <a href="./databases#shell">shell de um banco</a>, atualizar ou migrar um banco, fazer failover e importar dados.</li><li><strong>O administrador do Orbit</strong> é quem instalou o Orbit. Servidores, atualizações do Orbit e novos workspaces ficam com ele, e ele é proprietário de todos os workspaces. Isso é separado dos papéis de workspace, e por enquanto o Orbit tem um administrador.</li><li><strong>No console</strong>, o que o seu papel não pode fazer fica desabilitado e diz qual papel é preciso. O seletor de workspace mostra o seu papel.</li></ul><h2 id="inviting" tabindex="-1">Convidando alguém <a class="header-anchor" href="#inviting" aria-label="Permalink to &quot;Convidando alguém {#inviting}&quot;">​</a></h2><ol><li>Em <strong>Configurações → Membros</strong>, digite o email e escolha o papel. Admins convidam admins, desenvolvedores e leitores; só proprietários convidam proprietários.</li><li>Quando o <a href="./notifications#email-setup">email está configurado</a>, o Orbit envia o link por email para essa pessoa. Senão, ou se o servidor de email recusar, mande o link pelo canal que você usa com ela. De um jeito ou de outro, o link aparece uma vez, funciona uma vez, por sete dias, e o Orbit guarda só um hash dele.</li><li>A pessoa abre o link, cria uma conta com nome e uma senha de pelo menos 12 caracteres e cai no workspace. Quem já tem conta neste Orbit entra com ela e ganha o novo workspace ao lado dos que já tinha. Com o <a href="./sign-in#invitations">login com GitHub ou Google</a> configurado, a pessoa também pode entrar com um provedor que verificou o email convidado.</li></ol><ul><li><strong>Convites pendentes</strong> aparecem abaixo dos membros e podem ser revogados. Convidar o mesmo endereço de novo substitui o link anterior.</li><li><strong>Tentativas com erro</strong> ao aceitar são limitadas como no login.</li></ul><h2 id="removing" tabindex="-1">Mudando papéis e removendo <a class="header-anchor" href="#removing" aria-label="Permalink to &quot;Mudando papéis e removendo {#removing}&quot;">​</a></h2><ul><li><strong>Papéis</strong> mudam na linha do membro. Admins mudam desenvolvedores e leitores; proprietários mudam qualquer um.</li><li><strong>O último proprietário</strong> mantém o papel e não pode sair, então um workspace sempre tem alguém que pode gerenciá-lo.</li><li><strong>Remover alguém desconecta a pessoa de todo lugar na hora</strong>, e o console aberto dela para de receber atualizações. A conta continua, então ela pode ser convidada de novo.</li><li><strong>Sair:</strong> qualquer pessoa sai de um workspace pela própria linha e continua conectada nos outros workspaces de que participa.</li></ul><h2 id="visibility" tabindex="-1">O que cada pessoa vê <a class="header-anchor" href="#visibility" aria-label="Permalink to &quot;O que cada pessoa vê {#visibility}&quot;">​</a></h2><ul><li>Listas, a atividade e as atualizações ao vivo só trazem os workspaces de que a pessoa participa. Um link para um projeto de outro workspace responde como se ele não existisse.</li><li>Servidores são compartilhados, então todos veem, mas só o administrador muda.</li><li>Scripts e CI usam <a href="./api-tokens">tokens de API</a>, que agem com um papel próprio em vez da conta de uma pessoa.</li><li>A API confere o papel em toda operação. O contrato diz o papel que cada operação exige em <code>x-orbit-role</code>, e um papel baixo demais recebe <code>403 roleRequired</code> com o papel necessário.</li></ul>',12)])])}const b=o(s,[["render",t]]);export{u as __pageData,b as default};
